  const rank=manifest?q.manifestDestinyRank:boost?q.abilityBoostRank:q.adeptRank,maxRank=manifest?q.maxManifestDestinyRank:boost?q.maxAbilityBoostRank:q.maxRank,cost=manifest?q.manifestDestinyNextCost:boost?q.abilityBoostNextCost:q.nextCost,duration=manifest?TRAINING_POLICY.manifestDestiny.durationMs:boost?TRAINING_POLICY.abilityBoost.durationMs:TRAINING_POLICY.durationMs;
  const ownJob=q.active?.id===id,otherJob=!!q.active&&!ownJob,capped=rank>=maxRank,readOnly=trainingReadOnly(),canStart=(manifest?q.canStartManifestDestiny:boost?q.canStartAbilityBoost:q.canStart)&&!readOnly;
  const levelLocked=manifest?q.manifestDestinyLevelLocked:boost&&q.abilityBoostLevelLocked,levelCap=manifest?q.manifestDestinyLevelCap:q.abilityBoostLevelCap,requiredLevel=manifest?(rank+1)*TRAINING_POLICY.manifestDestiny.levelsPerRank:rank+1;
