  return `<section class="panel ability-card ${slot>=0?'slotted':''}"><div class="ability-symbol ${conflagration?'mp':supportive?'supportive':def.pool}">${icon(conflagration?'flame':supportive?'heart':{hp:'heart',mp:'drop',sp:'spark'}[def.pool])}</div><div class="eyebrow">${esc(def.name)}</div><h2>${conflagration?'烈焰擴散':supportive?'強化治癒':potion?def.pool==='hp'?'強化生命藥水':def.pool==='mp'?'強化魔力藥水':'強化靈力藥水':names[def.pool]}</h2><p>${description}</p><div class="ability-rank"><strong>${rank?'已學習 '+rank+' 階':'尚未學習'}</strong><span>${slot>=0?(conflagration?'已裝配於 ':'生效於 ')+(supportive?'Supportive':'Major')+' '+(slot+1):rank?'尚未裝配':'無效果'}</span></div><div class="ability-preview">${preview}</div><button class="primary-button" data-ability-buy="${esc(def.id)}" ${q.ok?'':'disabled'} title="${esc(q.error||'學習後仍須裝配')}">${next?'學習 '+(rank+1)+' 階 · '+next.cost+' AP':def.furtherRanks==='deferred'?'已完成 '+def.ranks.length+' 階 · 後續未開放':'已達 '+def.ranks.length+' 階上限'}</button><small class="ability-gate">${next?'此階需要 Lv.'+Math.max(1,next.minLevel):cap}${supportive?'；Cure 施放須 Lv.5':''}</small>${abilitySlotPicker(def)}</section>`;
