function downloadRawSave(raw,archive=false){const blob=new Blob([raw],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`vesper-${archive?'legacy-archive':'save'}-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('存檔已交由瀏覽器下載，請確認檔案已保存');}
function exportSave(){let raw=historyUpgradePending&&migrationArchiveRaw?migrationArchiveRaw:serializeGame(game);if(preserveBadSave&&!migrationArchiveRaw){try{raw=storage.getItem(SAVE_KEY)||originalSourceRaw||raw}catch{}}downloadRawSave(raw,historyUpgradePending);}
function exportArchive(){if(migrationArchiveRaw)downloadRawSave(migrationArchiveRaw,true);else exportSave();}
/** Import/reset stage a save before replacing the visible session or clearing read-only guards. */
async function readImportFile(file){
  if(!requireWritable(true,true))return;clearAbilitySlotChoices();const ownerEpoch=ownershipEpoch;
  const token={};importReadToken=token;
  if(!file)return;
  clearImportPreview();
  if(ui.modal==='import'){ui.modal='settings';renderModal();}
  if(file.size>MAX_LEGACY_RECOVERY_BYTES){toast('檔案超過 20 MB 舊檔恢復上限，未載入');return;}
  try{
    const raw=await file.text();
    if(importReadToken!==token||ownershipEpoch!==ownerEpoch||!requireWritable(false,true))return;
    const data=restoreGame(raw)||recoverLegacyGame(raw);
    if(!data){toast('檔案格式或規則版本不相容，原存檔未變更');return;}
    ui.importGame=data;ui.importLegacy=JSON.parse(raw).schemaVersion===1;
    ui.importArchiveRaw=ui.importLegacy?raw:null;openModal('import');
  }catch{
    if(importReadToken===token)toast('檔案讀取失敗，原存檔未變更');
  }
}
function replaceGameAfterSave(candidate,{archiveRaw=null,message='進度已保存'}={}){
  clearAbilitySlotChoices();
  if(!requireWritable(true,true))return false;
  const saved=saveLocalGame(storage,candidate,{owner:saveOwner,expectedRaw:expectedPrimaryRaw,allowLegacyReplacement:true});
  if(!acceptSaveResult(saved,{dirty:false})){toast(saved.error);return false;}
  game=candidate;
  if(archiveRaw)migrationArchiveRaw=archiveRaw;
  historyUpgradePending=false;preserveBadSave=false;loadWarning='';
  ui.importGame=null;ui.importArchiveRaw=null;ui.importLegacy=false;
  ui.selectedItem=game.equipped.weapon;ui.view=navigateView('battle',{replace:true});
  ui.busy=false;ui.feedback=[];ui.lastAction=null;
  ui.trainingNotice='';ui.trainingError='';ui.pendingTraining=null;
  closeModal();render();toast(saved.warning||message);
  return true;
}
