document.addEventListener('change',async event=>{if(event.target.id==='battle-log-filter'){chooseLogFilter(event.target);return;}if(event.target.dataset.abilitySlotSelect){chooseAbilitySlot(event.target);return;}if((event.target.dataset.protectionItem||event.target.id==='import-file')&&!requireWritable(true,event.target.id==='import-file')){render();return;}if(event.target.id==='fragment-quantity'){ui.fragmentQty=Number(event.target.value);render();return;}if(event.target.id==='soulbind-protection-confirm'){if(ui.modal==='soulbind'&&ui.pendingSoulbind?.requiresProtectionConfirmation){ui.soulbindProtectionConfirmed=event.target.checked===true;renderModal();$('#soulbind-protection-confirm')?.focus();}return;}if(event.target.id==='supply-quantity'){closeModal();ui.supplyQty=Number(event.target.value);render();return;}if(historyUpgradePending&&event.target.dataset.protectionItem){render();openModal('audit-upgrade');return;}if(event.target.dataset.protectionItem){apply(setEquipmentProtection(game,event.target.dataset.protectionItem,event.target.value),'裝備保護狀態已保存');return;}if(event.target.id==='attribute-step'){ui.attributeStep=Number(event.target.value);render();return;}if(event.target.id==='import-file')await readImportFile(event.target.files[0]);});
document.addEventListener('keydown',event=>{if(ui.modal){if(event.key==='Escape'&&!['welcome','audit-upgrade'].includes(ui.modal)){closeModal();return;}if(event.key==='Tab'){const nodes=[...$('#overlays').querySelectorAll('button:not([disabled]),a,input,select')].filter(n=>!n.classList.contains('sr-only'));const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}return;}if(ignoreBattleHotkey(event)||ui.view!=='battle')return;if(!requireWritable(false))return;if(historyUpgradePending){event.preventDefault();openModal('audit-upgrade');return;}if(event.code==='Space'&&game.battle?.phase==='round-complete'){event.preventDefault();ui.feedback=[];apply(continueRound(game));return;}if(['ArrowLeft','ArrowRight'].includes(event.key)&&active()){const living=game.battle.enemies.filter(e=>e.hp>0),index=living.findIndex(e=>e.id===game.battle.targetId),next=living[(index+(event.key==='ArrowRight'?1:-1)+living.length)%living.length];if(next){event.preventDefault();apply(selectTarget(game,next.id));}return;}const ids=['attack','fire','cure','scan','defend','focus','spirit'];const id=ids[Number(event.key)-1]||(event.key.toLowerCase()==='h'?'healthPotion':event.key.toLowerCase()==='m'?'manaPotion':event.key.toLowerCase()==='s'?'spiritPotion':null);if(id){event.preventDefault();act(id)}});
window.addEventListener('popstate',()=>{ui.view=readView(location.hash);closeModal();render()});
window.addEventListener('pagehide',()=>{if(ui.modal==='log')closeModal();clearFirePreview();if(ui.modal==='mastery-slot')closeModal();ui.pendingMasterySlot=null;clearTrainingReview();writerReady=false;ownershipEpoch++;importReadToken=null;clearAbilitySlotChoices();saveOwner?.release('分頁已離開；返回時需重新取得寫入權');});
window.addEventListener('pageshow',()=>{if(!saveConflict&&!unsavedChanges&&!writerReady&&saveOwner?.status!=='acquiring')ownershipReady=acquireWriter();else render();});
window.addEventListener('storage',event=>{if((event.key===SAVE_KEY||event.key===null)&&writerReady&&event.newValue!==expectedPrimaryRaw)freezeWrites('受保護存檔已由其他來源更新；本頁停止寫入，請先匯出備份。',{conflict:true});});
